#include <stdio.h>
#include <stdlib.h>

#define MAX_NODES 100

// 定义邻接表节点结构体
typedef struct AdjListNode {
    int dest;  // 目标节点
    struct AdjListNode* next;  // 指向下一个邻接表节点的指针
} AdjListNode;

// 定义邻接表结构体
typedef struct AdjList {
    AdjListNode* head;  // 邻接表的头节点指针
} AdjList;

// 定义图结构体
typedef struct Graph {
    int numNodes;  // 节点数量
    AdjList* adjLists;  // 邻接表数组
} Graph;

// 创建邻接表节点
AdjListNode* createAdjListNode(int dest) {
    AdjListNode* newNode = (AdjListNode*)malloc(sizeof(AdjListNode));  // 分配内存
    newNode->dest = dest;  // 设置目标节点
    newNode->next = NULL;  // 初始化下一个节点指针为 NULL
    return newNode;  // 返回新创建的邻接表节点
}

// 创建图
Graph* createGraph(int numNodes) {
    Graph* graph = (Graph*)malloc(sizeof(Graph));  // 分配内存
    graph->numNodes = numNodes;  // 设置节点数量

    // 为邻接表分配内存
    graph->adjLists = (AdjList*)malloc(numNodes * sizeof(AdjList));

    // 初始化邻接表
    for (int i = 0; i < numNodes; i++) {
        graph->adjLists[i].head = NULL;  // 将每个邻接表的头节点初始化为 NULL
    }

    return graph;  // 返回创建的图
}

// 添加边到图中
void addEdge(Graph* graph, int src, int dest) {
    // 创建从源节点到目标节点的边
    AdjListNode* newNode = createAdjListNode(dest);  // 创建新的邻接表节点
    newNode->next = graph->adjLists[src].head;  // 将新节点插入到源节点的邻接表头部
    graph->adjLists[src].head = newNode;

    // 创建从目标节点到源节点的边（无向图）
    newNode = createAdjListNode(src);  // 创建新的邻接表节点
    newNode->next = graph->adjLists[dest].head;  // 将新节点插入到目标节点的邻接表头部
    graph->adjLists[dest].head = newNode;

// 深度优先搜索遍历
void DFS(Graph* graph, int startNode, int* visited) {
    visited[startNode] = 1;  // 标记当前节点已访问
    printf("%c ", startNode + 'a');  // 输出当前节点

    AdjListNode* curr = graph->adjLists[startNode].head;  // 获取当前节点的邻接表
    while (curr!= NULL) {  // 遍历邻接表
        if (!visited[curr->dest]) {  // 如果目标节点未被访问
            DFS(graph, curr->dest, visited);  // 递归访问目标节点
        }
        curr = curr->next;  // 移动到下一个邻接表节点
    }

// 广度优先搜索遍历
void BFS(Graph* graph, int startNode) {
    int* visited = (int*)malloc(graph->numNodes * sizeof(int));  // 创建访问标记数组
    for (int i = 0; i < graph->numNodes; i++) {  // 初始化访问标记为 0
        visited[i] = 0;
